import type { Jurisdiction } from './jurisdictions'
export type ElementCategory = 'official' | 'department' | 'body' | 'group'
export type OfficialType = 'prime-minister' | 'cabinet-minister' | 'junior-minister' | 'civil-servant' | 'independent'
export type DepartmentType = 'ministerial' | 'non-ministerial' | 'agency' | 'division-directorate'
export type BodyType = 'executive-ndpb' | 'advisory-ndpb' | 'public-corporation' | 'royal-charter-body' | 'tribunal' | 'other'
export type GroupType = 'cabinet' | 'other-group'

// ── Tag system ────────────────────────────────────────────────────────────────
// tagCategory: 'type' = what kind of body/role it is
//              'sector' = the policy area(s) it operates in
export interface TagDefinition {
  id: string
  label: string
  tagCategory: 'type' | 'sector'
  colour: string   // hex colour for badge rendering
}

