export interface GovElement {
  id: string
  name: string
  category: ElementCategory
  subtype: OfficialType | DepartmentType | BodyType | GroupType
  description: string
  role?: string
  currentHolder?: string
  currentHolderSince?: string   // ISO date (YYYY-MM-DD) the current holder took office
  infoUrl?: string
  parentIds: string[]
  secondaryParentIds?: string[]
  tags?: string[]
  jurisdictions?: Jurisdiction[]
}

export interface ElementRelationship {
  id: string
  label: string
  type: 'reports-to' | 'oversees' | 'member-of'
}

